production.storyboard:
[
  {
    "panelNumber": 1,
    "originalText": "“Đúng quy trình?” Vương tổng cười lạnh. “Tài liệu cô viết, Tiểu Chu đọc không hiểu nổi!”",
    "description": "Composition: Medium shot. Vương Tổng stands up abruptly or slams the document on the desk. \nLighting: Bright office lighting. \nAction: Vương Tổng (Male, 50, Outfit 2: Dark blue business suit) throws a thin document onto his desk with a scoff, his expression mocking and angry. He looks directly at Lâm Vũ.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 2,
    "originalText": "“Không hiểu thì có thể hỏi tôi.”",
    "description": "Composition: Close-up on Lâm Vũ. \nLighting: Bright office lighting. \nAction: Lâm Vũ (Female, 35, Outfit 3: Pale blue chiffon blouse) stands calmly, her expression unruffled and challenging.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 3,
    "originalText": "“Hỏi cô? Mấy cái mật khẩu cô đưa toàn sai!” Tôi không đáp.",
    "description": "Composition: Two-shot. \nLighting: Bright office lighting. \nAction: Vương Tổng (Outfit 2) shouts angrily, gesturing wildly. Lâm Vũ (Outfit 3) stands silent and impassive, maintaining eye contact.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 4,
    "originalText": "Vương tổng đứng dậy, bước đến trước mặt tôi. “Lâm Vũ, đừng tưởng tôi không biết cô đang tính gì. Muốn tăng lương chứ gì? Muốn thăng chức chứ gì? Được, cô nói ra con số đi!”",
    "description": "Composition: Low angle shot looking up at Vương Tổng standing close to Lâm Vũ. \nLighting: Vương Tổng casts a shadow over Lâm Vũ. \nAction: Vương Tổng (Outfit 2) moves close to Lâm Vũ, looking down at her with an arrogant, bargaining expression.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 5,
    "originalText": "“Vương tổng, tôi đã ký nhận việc với công ty mới rồi.”",
    "description": "Composition: Close-up on Lâm Vũ. \nLighting: Bright office lighting. \nAction: Lâm Vũ (Outfit 3) speaks clearly and calmly, dropping the bombshell.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 6,
    "originalText": "Vương tổng sững người. “Gì cơ?” “Lương năm 600 ngàn, chức vụ Giám đốc kỹ thuật.”",
    "description": "Composition: Close-up on Vương Tổng's face. \nLighting: Bright office lighting. \nAction: Vương Tổng (Outfit 2) freezes, his eyes widening in shock and disbelief.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 7,
    "originalText": "Không khí lặng đi năm giây. Sắc mặt Vương tổng thay đổi. “Cô tìm được rồi sao?” “Đúng vậy.”",
    "description": "Composition: Two-shot. \nLighting: Tense atmosphere. \nAction: Vương Tổng (Outfit 2) stares at Lâm Vũ (Outfit 3), his expression shifting from shock to panic. Lâm Vũ maintains a steady, confirming gaze.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 8,
    "originalText": "Vương tổng lùi về sau hai bước, ngồi phịch xuống ghế.",
    "description": "Composition: Medium shot. \nLighting: Bright office lighting. \nAction: Vương Tổng (Outfit 2) stumbles back and collapses heavily into his office chair, looking defeated.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 9,
    "originalText": "Tôi nhìn ông ta. Lần đầu tiên tôi thấy nét mặt này ở ông ta. Bối rối. Sợ hãi. Và… hối hận?",
    "description": "Composition: Close-up on Vương Tổng's face. \nLighting: Shadows on his face. \nAction: Vương Tổng (Outfit 2) looks up with a complex expression of confusion, fear, and regret.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 10,
    "originalText": "“Lâm Vũ,” Vương tổng cười gượng một tiếng, “Cô đừng đùa nữa.” “Tôi không đùa.”",
    "description": "Composition: Medium shot. \nLighting: Bright office lighting. \nAction: Vương Tổng (Outfit 2) forces a weak, fake smile, trying to deny reality. Lâm Vũ (Outfit 3) remains serious.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 11,
    "originalText": "“600 ngàn?” Vương tổng lắc đầu, “Không thể nào. Cô 35 tuổi rồi, ai lại ra giá đó?”",
    "description": "Composition: Medium shot of Vương Tổng. \nLighting: Bright office lighting. \nAction: Vương Tổng (Outfit 2) shakes his head in disbelief and disdain, still clinging to his prejudices.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 12,
    "originalText": "Tôi đưa điện thoại ra. Trên màn hình là ảnh chụp thư mời nhận việc.",
    "description": "Composition: Close-up of Lâm Vũ's hand holding a phone. \nLighting: Phone screen glow. \nAction: The phone screen clearly shows an Offer Letter document.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 13,
    "originalText": "Vương tổng nhìn rất lâu. Sau đó ông ta ngẩng đầu lên nhìn tôi, ánh mắt phức tạp. “Lâm Vũ, sao cô không nói sớm?”",
    "description": "Composition: Medium shot. \nLighting: Bright office lighting. \nAction: Vương Tổng (Outfit 2) looks up from the phone to Lâm Vũ with a weak, reproachful look.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 14,
    "originalText": "Tôi cười. “Vương tổng, tôi đã nói rất nhiều lần rồi, nhưng ông không nghe.”",
    "description": "Composition: Close-up on Lâm Vũ. \nLighting: Bright office lighting. \nAction: Lâm Vũ (Outfit 3) smiles a bitter, sarcastic smile.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 15,
    "originalText": "Vương tổng trầm mặc. “Vậy thế này,” ông nói, “Tôi tăng lương cô lên 20 ngàn, ở lại đi.”",
    "description": "Composition: Medium shot of Vương Tổng. \nLighting: Bright office lighting. \nAction: Vương Tổng (Outfit 2) leans forward, making a desperate bargaining gesture.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 16,
    "originalText": "20 ngàn. Từ 8 ngàn tăng lên 20 ngàn. Tăng 150%. Nhưng bên kia mời với mức lương 600 ngàn một năm.",
    "description": "Composition: Close-up on Lâm Vũ's face. \nLighting: Bright office lighting. \nAction: Lâm Vũ (Outfit 3) has a thoughtful but ultimately dismissive expression as she compares the numbers in her head.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 17,
    "originalText": "“Cảm ơn ông,” tôi nói, “Nhưng tôi đã quyết định rồi.”",
    "description": "Composition: Medium shot. \nLighting: Bright office lighting. \nAction: Lâm Vũ (Outfit 3) shakes her head politely but firmly.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 18,
    "originalText": "Sắc mặt Vương tổng càng lúc càng khó coi. “Cô có biết, nếu cô đi, công ty sẽ bị động thế nào không?” “Tôi biết.”",
    "description": "Composition: Two-shot. \nLighting: Tense lighting. \nAction: Vương Tổng's (Outfit 2) face darkens with anger. He glares at Lâm Vũ. Lâm Vũ (Outfit 3) meets his glare calmly.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 19,
    "originalText": "“Biết mà vẫn đi?” Tôi nhìn ông ta. “Vương tổng, ông từng nói, công ty không có ai vẫn vận hành được.”",
    "description": "Composition: Close-up on Lâm Vũ. \nLighting: Bright office lighting. \nAction: Lâm Vũ (Outfit 3) speaks with a sharp, reminding tone.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 20,
    "originalText": "“Cái đó là tôi…” “Ông nói, ba chân cóc thì hiếm, người hai chân thì đầy ngoài kia.”",
    "description": "Composition: Medium shot of Vương Tổng. \nLighting: Bright office lighting. \nAction: Vương Tổng (Outfit 2) stammers, looking embarrassed and caught in his own words.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 21,
    "originalText": "Mặt Vương tổng đỏ bừng. “Cô nghĩ cô là ai? Công ty không có cô thì không vận hành được à? Tôi nói cho cô biết, ba chân cóc thì hiếm, người hai chân thì có cả đống!”",
    "description": "Composition: Low angle shot. \nLighting: Harsh lighting. \nAction: Vương Tổng (Outfit 2) stands up abruptly, shouting with a red face, losing control.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 22,
    "originalText": "Tôi cười. “Ông nói đúng, ba chân cóc thì khó tìm. Nhưng con cóc có thể nhảy được hay không, còn phải xem cái giếng.”",
    "description": "Composition: Close-up on Lâm Vũ. \nLighting: Bright office lighting. \nAction: Lâm Vũ (Outfit 3) smiles a victorious, meaningful smile.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 23,
    "originalText": "Vương tổng sững người.",
    "description": "Composition: Medium shot of Vương Tổng. \nLighting: Bright office lighting. \nAction: Vương Tổng (Outfit 2) stands frozen, stunned by her comeback.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 24,
    "originalText": "Tôi quay người rời khỏi văn phòng. Phía sau vang lên tiếng gào của ông ta: “Lâm Vũ! Cô sẽ hối hận!” Tôi không quay đầu lại.",
    "description": "Composition: View from the office doorway looking out. \nLighting: Bright corridor. \nAction: Lâm Vũ (Outfit 3) walks away decisively. In the background, out of focus, Vương Tổng (Outfit 2) is shouting.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 25,
    "originalText": "Tin tức nhanh chóng lan ra. Lâm Vũ sắp rời công ty, tìm được công việc lương 600 ngàn một năm. Cả công ty rúng động.",
    "description": "Composition: Wide shot of the General Office Area. \nLighting: Bright office lighting. \nAction: Groups of employees (off-screen characters) are gathered, whispering and gossiping excitedly.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 26,
    "originalText": "Có người ngưỡng mộ, có người ghen tỵ, có người hả hê. Nhưng nhiều hơn cả là hoảng loạn. Vì họ cuối cùng cũng nhận ra, nếu không có tôi, công ty này thật sự có thể sụp đổ.",
    "description": "Composition: Montage of employee faces. \nLighting: Bright office lighting. \nAction: Various employees showing expressions of envy, admiration, and fear/panic.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 27,
    "originalText": "Hệ thống khách hàng, tôi xây. Hệ thống tài chính, tôi xây. Hệ thống chuỗi cung ứng, tôi xây. Ba hệ thống cốt lõi, đều là tôi một tay làm từ số 0.",
    "description": "Composition: Artistic shot. Lâm Vũ stands in the center, supporting metaphorical pillars labeled 'Customer', 'Finance', 'Supply Chain'. \nLighting: Dramatic spotlight. \nAction: Lâm Vũ (Outfit 3) stands strong, holding up the weight of the company's systems.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 28,
    "originalText": "Code do tôi viết, mật khẩu do tôi đặt, chú thích cũng do tôi gõ. Không có tôi, chỉ còn lại một đống mã hóa chẳng ai hiểu.",
    "description": "Composition: Close-up on a computer screen reflecting in Lâm Vũ's glasses. \nLighting: Screen glow. \nAction: Complex lines of code are visible on the screen and reflected in her glasses. She looks at it with ownership.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 29,
    "originalText": "Tiểu Chu tìm tôi mấy lần. “Chị Lâm, chị đưa em mật khẩu hệ thống đi.”",
    "description": "Composition: Medium shot. \nLighting: Bright office lighting. \nAction: Tiểu Chu (Outfit 2: Cream blazer) follows Lâm Vũ (Outfit 3) who is walking in the office, pleading with her.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 30,
    "originalText": "“Đã nói rồi mà, mật khẩu phải bàn giao miệng, cần ba người chứng kiến.” “Vậy bao giờ?” “Trước khi tôi rời đi.”",
    "description": "Composition: Two-shot. \nLighting: Bright office lighting. \nAction: Lâm Vũ (Outfit 3) stops briefly to answer coolly, then continues walking. Tiểu Chu (Outfit 2) looks frustrated.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 31,
    "originalText": "“Chị sắp đi rồi còn gì!” “Vậy thì tranh thủ lên.”",
    "description": "Composition: Medium shot. \nLighting: Bright office lighting. \nAction: Tiểu Chu (Outfit 2) stamps her foot in anxiety. Lâm Vũ (Outfit 3) shrugs indifferently.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 32,
    "originalText": "Tiểu Chu sắp khóc rồi. Nhưng cô ta vẫn cố nhịn. Vì cô ta còn việc quan trọng hơn phải làm, chứng minh mình không phải bình hoa di động.",
    "description": "Composition: Close-up on Tiểu Chu's face. \nLighting: Bright office lighting. \nAction: Tiểu Chu (Outfit 2) holds back tears, biting her lip, trying to look determined.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 33,
    "originalText": "Chiều hôm đó, Tiểu Chu làm một báo cáo trước toàn thể công ty.",
    "description": "Composition: Wide shot of the Meeting Room. \nLighting: Bright meeting room lighting. \nAction: Tiểu Chu (Outfit 2) stands at the podium/projector screen, presenting to a room full of people.",
    "timeOfDay": "Afternoon (Week 3)"
  },
  {
    "panelNumber": 34,
    "originalText": "Chủ đề là “Kế hoạch phát triển tương lai của bộ phận kỹ thuật”. PPT rất đẹp, biểu đồ rất chuyên nghiệp. Nhưng nội dung, hoàn toàn là phương án tôi đã làm từ ba năm trước.",
    "description": "Composition: Over-the-shoulder shot from Lâm Vũ's perspective. \nLighting: Dimmed room, bright projector screen. \nAction: Tiểu Chu (Outfit 2) points at a slide. Lâm Vũ (Outfit 3) sits in the audience, recognizing the content.",
    "timeOfDay": "Afternoon (Week 3)"
  },
  {
    "panelNumber": 35,
    "originalText": "Vương tổng nghe mà gật gù liên tục. “Tiểu Chu làm tốt lắm, có ý tưởng.”",
    "description": "Composition: Medium shot of Vương Tổng. \nLighting: Meeting room lighting. \nAction: Vương Tổng (Outfit 2) sits in the front row, nodding and clapping approvingly.",
    "timeOfDay": "Afternoon (Week 3)"
  },
  {
    "panelNumber": 36,
    "originalText": "Tôi ngồi ở góc, nhìn cảnh này, không nói gì.",
    "description": "Composition: Medium shot of Lâm Vũ. \nLighting: Shadowed corner of the meeting room. \nAction: Lâm Vũ (Outfit 3) sits quietly in the back/corner, watching with a look of silent contempt.",
    "timeOfDay": "Afternoon (Week 3)"
  },
  {
    "panelNumber": 37,
    "originalText": "Tan họp, Tiểu Chu bước đến trước mặt tôi. “Chị Lâm, chị thấy bài thuyết trình hôm nay của em thế nào?”",
    "description": "Composition: Two-shot. \nLighting: Bright meeting room lighting (lights back on). \nAction: Tiểu Chu (Outfit 2) approaches Lâm Vũ (Outfit 3) with a smug, proud expression, wanting validation.",
    "timeOfDay": "Afternoon (Week 3)"
  },
  {
    "panelNumber": 38,
    "originalText": "Tôi nhìn cô ta. “Tiểu Chu, phương án đó, là tôi làm ba năm trước.”",
    "description": "Composition: Close-up on Lâm Vũ. \nLighting: Bright meeting room lighting. \nAction: Lâm Vũ (Outfit 3) looks directly at Tiểu Chu, delivering the truth calmly but cuttingly.",
    "timeOfDay": "Afternoon (Week 3)"
  }
]

